INSERT INTO songs VALUES (1,'Agar Tum Saath Ho','agar-tum-saath-ho','The song "Agar Tum Saath Ho" is from the movie Tamasha (2015), starring Ranbir Kapoor and Deepika Padukone. It is sung by Alka Yagnik and Arijit Singh, with music composed by A.R. Rahman and lyrics written by Irshad Kamil. The song expresses themes of love, longing, and the emotional depth of companionship, making it one of the most beloved tracks in Bollywood.',NULL,'https://res.cloudinary.com/xrwvu9pm/video/upload/v1786069412/Agar-Tum-Saath-Ho-FULL-AUDIO-Son_sak9oz.mp3','https://res.cloudinary.com/xrwvu9pm/image/upload/v1786069825/agar_tum_sath_ho_o0ztzm.jpg',322,'Hindi','2015-10-16',1,1,0,0,1,'2026-08-07 03:08:18','2026-08-22 10:58:12',NULL),(2,'Channa Mereya','channa-mereya',NULL,NULL,'https://res.cloudinary.com/xrwvu9pm/video/upload/v1786069415/Channa-Mereya-Lyric-Video-Ae-Dil_wr3fwd.mp3','https://res.cloudinary.com/xrwvu9pm/image/upload/v1786069910/channa_mereya_tgjuab.jpg',325,'Hindi','2016-09-29',1,1,0,0,1,'2026-08-07 16:58:12','2026-08-22 10:58:12',NULL),(3,'Hamari Adhuri Kahani','hamari-adhuri-kahani',NULL,NULL,'https://res.cloudinary.com/xrwvu9pm/video/upload/v1786069411/Arijit-Singh-Humari-Adhuri-Kahan_ykl8cn.mp3','https://res.cloudinary.com/xrwvu9pm/image/upload/v1786069911/Hamari-Adhuri-Kahani-Hindi-2015-500x500_loomze.jpg',325,'Hindi','2015-05-21',0,0,0,0,1,'2026-08-07 16:58:12','2026-08-22 10:58:12',NULL),(4,'Banke Hawa Mein','banke-hawa-mein',NULL,NULL,'https://res.cloudinary.com/xrwvu9pm/video/upload/v1786069410/Banke-Hawa-Mein-Bezubaan-Mein-Of_hto8wk.mp3','https://res.cloudinary.com/xrwvu9pm/image/upload/v1786426491/Banke_Hawa_Mein_Bezubaan_Mein_intqtp.jpg',202,'Hindi','2025-08-25',0,0,0,0,1,'2026-08-07 16:58:12','2026-08-22 10:58:12',NULL),(5,'Maine Royaa','maine-royaa',NULL,NULL,'https://res.cloudinary.com/xrwvu9pm/video/upload/v1786069406/Maine-Royaa-1_ilcjxj.mp3','https://res.cloudinary.com/xrwvu9pm/image/upload/v1786069913/mai_royaa_ccodvv.jpg',315,'Hindi','2021-07-19',0,0,0